import sys
from collections import deque

def read_input():
    input = sys.stdin.read
    data = input().split()
    n = int(data[0])
    m = int(data[1])
    grid = []
    index = 2
    for i in range(n):
        row = list(data[index])
        grid.append(row)
        index += 1
    return n, m, grid

def is_valid(x, y, n, m):
    return 0 <= x < n and 0 <= y < m

def bfs(grid, start_x, start_y):
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    queue = deque([(start_x, start_y)])
    visited = set()
    visited.add((start_x, start_y))
    size = 0

    while queue:
        x, y = queue.popleft()
        size += 1

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if is_valid(nx, ny, len(grid), len(grid[0])) and grid[nx][ny] == '*' and (nx, ny) not in visited:
                visited.add((nx, ny))
                queue.append((nx, ny))

    return size

def solve(n, m, grid):
    stars = []
    for i in range(n):
        for j in range(m):
            if grid[i][j] == '*':
                size = bfs(grid, i, j)
                stars.append((i, j, size))
                # Mark all cells in the star as visited
                queue = deque([(i, j)])
                while queue:
                    x, y = queue.popleft()
                    grid[x][y] = '.'
                    for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        nx, ny = x + dx, y + dy
                        if is_valid(nx, ny, n, m) and grid[nx][ny] == '*':
                            queue.append((nx, ny))

    if any('*' in row for row in grid):
        return -1

    return len(stars), stars

def main():
    n, m, grid = read_input()
    result, stars = solve(n, m, grid)
    if result == -1:
        print(result)
    else:
        print(result)
        for star in stars:
            print(star[0] + 1, star[1] + 1, star[2])

if __name__ == "__main__":
    main()

def draw_stars(n, m, grid):
    def is_valid_star(x, y, s):
        if x - s < 0 or x + s >= n or y - s < 0 or y + s >= m:
            return False
        if grid[x][y] != '*':
            return False
        for i in range(1, s + 1):
            if grid[x - i][y] != '*' or grid[x + i][y] != '*' or \
               grid[x][y - i] != '*' or grid[x][y + i] != '*':
                return False
        return True

    def dfs(x, y, visited):
        stack = [(x, y)]
        while stack:
            cx, cy = stack.pop()
            if (cx, cy) in visited:
                continue
            visited.add((cx, cy))
            for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nx, ny = cx + dx * s, cy + dy * s
                if 0 <= nx < n and 0 <= ny < m and grid[nx][ny] == '*' and (nx, ny) not in visited:
                    stack.append((nx, ny))

    stars = []
    visited = set()
    for i in range(n):
        for j in range(m):
            if grid[i][j] == '*' and (i, j) not in visited:
                s = 1
                while is_valid_star(i, j, s):
                    s += 1
                s -= 1
                if s > 0:
                    stars.append((i, j, s))
                    dfs(i, j, visited)

    if len(stars) > n * m:
        return -1

    return len(stars), stars

