        for j in range(m):
            if grid[i][j] == '*':
                s = 1
                while i - s >= 0 and grid[i - s][j] == '*':
                    s += 1
                if is_valid_star(i, j, s):
                    stars.append((i, j, s))
                    dfs(i, j, s)

    if len(stars) > n * m:
        return -1

    return len(stars), stars

