def draw_stars(n, m, grid):
    def is_valid(x, y, s):
        for i in range(max(0, x-s), min(n, x+s+1)):
            for j in range(max(0, y-s), min(m, y+s+1)):
                if grid[i][j] == '*' and (i != x or j != y):
                    return False
        return True

    def place_star(x, y, s):
        for i in range(max(0, x-s), min(n, x+s+1)):
            for j in range(max(0, y-s), min(m, y+s+1)):
                if grid[i][j] == '*':
                    grid[i][j] = '.'

    def remove_star(x, y, s):
        for i in range(max(0, x-s), min(n, x+s+1)):
            for j in range(max(0, y-s), min(m, y+s+1)):
                if grid[i][j] == '.':
                    grid[i][j] = '*'

    def backtrack(x, y, count):
        if x == n:
            return count
        if y == m:
            return backtrack(x + 1, 0, count)

        if grid[x][y] == '.':
            return backtrack(x, y + 1, count)

        best_count = -1
        for s in range(1, min(n, m) // 2 + 1):
            if is_valid(x, y, s):
                place_star(x, y, s)
                new_count = backtrack(x, y + 1, count + 1)
                if new_count != -1:
                    best_count = new_count
                remove_star(x, y, s)

        if best_count == -1:
            return backtrack(x, y + 1, count)

        return best_count

    result = backtrack(0, 0, 0)
    if result == -1:
        return [-1]

    stars = []
    for i in range(n):
        for j in range(m):
            if grid[i][j] == '.':
                continue
            for s in range(1, min(n, m) // 2 + 1):
                if is_valid(i, j, s):
                    stars.append([i + 1, j + 1, s])
                    break

    return [len(stars)] + stars

