def draw_stars(n, m, grid):
    def is_valid(x, y, s):
        for i in range(max(0, x-s), min(n, x+s+1)):
            for j in range(max(0, y-s), min(m, y+s+1)):
                if (i != x or j != y) and grid[i][j] == '*':
                    return False
        return True

    def place_star(x, y, s):
        for i in range(max(0, x-s), min(n, x+s+1)):
            for j in range(max(0, y-s), min(m, y+s+1)):
                if (i != x or j != y):
                    grid[i] = grid[i][:j] + 'S' + grid[i][j+1:]

    def remove_star(x, y, s):
        for i in range(max(0, x-s), min(n, x+s+1)):
            for j in range(max(0, y-s), min(m, y+s+1)):
                if (i != x or j != y):
                    grid[i] = grid[i][:j] + '.' + grid[i][j+1:]

    def solve():
        stars = []
        for i in range(n):
            for j in range(m):
                if grid[i][j] == '*':
                    for s in range(1, min(i, j, n-i-1, m-j-1)+1):
                        if is_valid(i, j, s):
                            place_star(i, j, s)
                            stars.append((i, j, s))
                            break
                    else:
                        continue
                    break
            else:
                continue
            break
        else:
            return -1
        return len(stars), stars

    result = solve()
    if result == -1:
        return "-1"
    else:
        num_stars, stars = result
        print(num_stars)
        for x, y, s in stars:
            print(x+1, y+1, s)

